#!/usr/bin/env python3
from pathlib import Path
import sys,re,json,gzip,base64,hashlib
p=Path(sys.argv[1]);h=p.read_text(encoding="utf-8")
ops=json.loads(gzip.decompress(base64.b64decode('')).decode())
for a,b,n in ops:
    if a not in h: raise SystemExit("V1.8.2 anchor missing: "+n)
    h=h.replace(a,b,1)
if "ACTION BODY DYNAMICS" not in h or "function evaluateActionBodyDynamics" not in h: raise SystemExit("V1.8.2 verify failed")
ids=re.findall(r'id="([^"]+)"',h)
if len(ids)!=len(set(ids)): raise SystemExit("duplicate ids")
p.write_text(h,encoding="utf-8")
print("Patched V1.8.2",len(h.encode()),hashlib.sha256(h.encode()).hexdigest())
